select pg_has_role('authenticator','applicant','member');

create schema if not exists private;
grant usage on schema private to fund_admin, expert, applicant;
grant usage on schema api to expert, applicant;

create or replace function private.login() returns text language sql stable as
$$ select coalesce(nullif(current_setting('request.jwt.claims',true),'')::json->>'login', current_user::text) $$;
create or replace function private.is_ai() returns boolean language sql stable as
$$ select coalesce(nullif(current_setting('request.headers',true),'')::json->>'x-client','') = 'ai' $$;
create or replace function private.my_company() returns int language sql stable security definer set search_path=pg_catalog,api as
$$ select company_id from api.app_user where login = private.login() $$;

-- R6, R7
alter table api.application alter column amount set not null;
alter table api.application add constraint application_amount_chk check (amount <> 'NaN'::numeric and amount >= 0);
alter table api.application add constraint application_revenue_chk check (revenue is null or revenue <> 'NaN'::numeric);
alter table api.application alter column status_id set default 20000;

-- audit & confirmation
create table api.audit(id bigserial primary key, ts timestamptz not null default now(), actor text, via text not null check (via in ('ai','human')), op text not null, app_id int);
create table api.confirmation(id bigserial primary key, actor text not null default private.login(), op text not null check (op in ('delete','bulk_update')), app_id int, created_at timestamptz not null default now());

create or replace function private.t_audit() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
begin
  insert into api.audit(actor,via,op,app_id) values (private.login(), case when private.is_ai() then 'ai' else 'human' end, tg_op, coalesce(case when tg_op='DELETE' then old.id else new.id end,0));
  return null;
end $$;
create trigger z_audit after insert or update or delete on api.application for each row execute function private.t_audit();

create or replace function private.consume(p_op text, p_app int) returns void language plpgsql security definer set search_path=pg_catalog,api as $$
declare v bigint;
begin
  select id into v from api.confirmation where actor=private.login() and op=p_op and app_id is not distinct from p_app and created_at > now()-interval '10 minutes' order by id limit 1 for update;
  if v is null then raise exception 'Требуется подтверждение человеком (%)', p_op using errcode='42501'; end if;
  delete from api.confirmation where id=v;
end $$;

create or replace function private.t_ai_delete() returns trigger language plpgsql as $$
begin
  if private.is_ai() then perform private.consume('delete', old.id); end if;
  return old;
end $$;
create trigger a_ai_delete before delete on api.application for each row execute function private.t_ai_delete();

create or replace function private.t_ai_bulk() returns trigger language plpgsql as $$
begin
  if private.is_ai() and (select count(*) from nt) > 1 then perform private.consume('bulk_update', null); end if;
  return null;
end $$;
create trigger a_ai_bulk after update on api.application referencing new table as nt for each statement execute function private.t_ai_bulk();

-- process rules R8-R10
create or replace function private.t_rules() returns trigger language plpgsql security definer set search_path=pg_catalog,api as $$
declare lim numeric;
begin
  if tg_op='INSERT' then
    if new.status_id <> 20000 then raise exception 'Новая заявка создаётся в статусе «Черновик»' using errcode='23514'; end if;
    return new;
  end if;
  if new.status_id <> old.status_id then
    if not ((select ord from api.status where id=new.status_id) = (select ord from api.status where id=old.status_id)+1 and new.status_id <> 20004 and old.status_id <> 20003)
       and not (old.status_id=20002 and new.status_id in (20003,20004)) then
      raise exception 'Недопустимый переход статуса' using errcode='23514';
    end if;
  end if;
  if new.status_id in (20003,20004) and (new.verdict is null or btrim(new.verdict)='') then
    raise exception 'Нужно заключение эксперта' using errcode='23514';
  end if;
  if new.status_id = 20003 then
    select funding_limit into lim from api.company where id=new.company_id;
    if lim is not null and new.amount > lim then raise exception 'Сумма превышает лимит компании' using errcode='23514'; end if;
  end if;
  return new;
end $$;
create trigger b_rules before insert or update on api.application for each row execute function private.t_rules();

-- grants
revoke all on api.audit, api.confirmation from public;
grant select on api.audit to fund_admin;
grant usage on sequence api.audit_id_seq to public; -- not needed for definer; harmless
revoke usage on sequence api.audit_id_seq from public;
grant select, insert on api.confirmation to fund_admin, expert, applicant;
grant delete on api.confirmation to fund_admin;
grant usage on sequence api.confirmation_id_seq, api.application_id_seq to fund_admin, applicant;

grant select on api.status to expert, applicant;
grant select on api.company to expert, applicant;
grant select (id,number,company_id,status_id,amount,revenue,description,verdict) on api.application to applicant;
grant insert (number,company_id,status_id,amount,revenue,description) on api.application to applicant;
grant update (number,company_id,status_id,amount,revenue,description) on api.application to applicant;
grant delete on api.application to applicant;
grant select on api.application to expert;
grant update (status_id,verdict,expert) on api.application to expert;

-- RLS
alter table api.application enable row level security;
alter table api.company enable row level security;
alter table api.app_user enable row level security;
alter table api.audit enable row level security;
alter table api.confirmation enable row level security;

create policy adm on api.application to fund_admin using (true) with check (true);
create policy app_sel on api.application for select to applicant using (company_id = private.my_company());
create policy app_ins on api.application for insert to applicant with check (company_id = private.my_company() and status_id=20000);
create policy app_upd on api.application for update to applicant using (company_id = private.my_company() and status_id in (20000,20001)) with check (company_id = private.my_company() and status_id in (20000,20001));
create policy app_del on api.application for delete to applicant using (company_id = private.my_company() and status_id=20000);
create policy exp_sel on api.application for select to expert using (status_id >= 20001);
create policy exp_upd on api.application for update to expert using (status_id in (20001,20002)) with check (status_id in (20002,20003,20004));

create policy adm on api.company to fund_admin using (true) with check (true);
create policy c_app on api.company for select to applicant using (id = private.my_company());
create policy c_exp on api.company for select to expert using (true);
create policy adm on api.app_user to fund_admin using (true) with check (true);
create policy adm on api.audit for select to fund_admin using (true);
create policy adm_c on api.confirmation to fund_admin using (true) with check (not private.is_ai() or false);
create policy c_sel on api.confirmation for select to expert, applicant using (actor = private.login());
create policy c_ins on api.confirmation for insert to expert, applicant with check (actor = private.login() and not private.is_ai());

